Add-Type -AssemblyName System.Drawing
$fs=Get-ChildItem Data -Filter *.jpg | Sort-Object Name;$cols=7;$tw=240;$th=175;$ox=55;$oy=42;$rows=[int][math]::Ceiling($fs.Count/$cols);$out=New-Object Drawing.Bitmap -ArgumentList ([int]($cols*$ox+$tw)),([int]($rows*$oy+$th));$g=[Drawing.Graphics]::FromImage($out);$g.Clear([Drawing.Color]::FromArgb(12,18,35));$g.SmoothingMode='HighQuality';for($i=0;$i -lt $fs.Count;$i++){try{$im=[Drawing.Image]::FromFile($fs[$i].FullName);$x=($i%$cols)*$ox+([int](Get-Random -Minimum -10 -Maximum 11));$y=[int]([math]::Floor($i/$cols)*$oy)+([int](Get-Random -Minimum -8 -Maximum 9));$scale=[math]::Max($tw/$im.Width,$th/$im.Height);$sw=[int]($tw/$scale);$sh=[int]($th/$scale);$sx=[int](($im.Width-$sw)/2);$sy=[int](($im.Height-$sh)/2);$g.DrawImage($im,[Drawing.Rectangle]::new($x,$y,$tw,$th),$sx,$sy,$sw,$sh,[Drawing.GraphicsUnit]::Pixel);$im.Dispose()}catch{}}$out.Save('mosaic.jpg',[Drawing.Imaging.ImageFormat]::Jpeg);$g.Dispose();$out.Dispose()
